.darma-loader-darma-b10-light-bulb { --accent: var(--loader-color, #fbbf24); --accent-2: var(--loader-secondary-color, #94a3b8); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b10-light-bulb span { width: 44%; height: 54%; border-radius: 50% 50% 46% 46%; background: radial-gradient(circle at 44% 34%, color-mix(in srgb, #fff 60%, var(--accent)), var(--accent)); box-shadow: 0 0 calc(var(--loader-size, 80px) * .28) var(--accent); position: relative; animation: darma-loader-darma-b10-light-bulb-bulb calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-darma-b10-light-bulb span::before { content: ''; position: absolute; top: 42%; left: 50%; width: 22%; height: 26%; margin-left: -11%; border: 2px solid color-mix(in srgb, #000 25%, var(--accent)); border-top: none; border-radius: 0 0 60% 60%; }
.darma-loader-darma-b10-light-bulb span::after { content: ''; position: absolute; bottom: -20%; left: 50%; width: 30%; height: 22%; margin-left: -15%; background: color-mix(in srgb, var(--accent-2) 45%, #64748b); border-radius: 3px 3px 5px 5px; }
@keyframes darma-loader-darma-b10-light-bulb-bulb { 0%, 100% { opacity: .5; box-shadow: 0 0 calc(var(--loader-size, 80px) * .08) var(--accent); } 50% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size, 80px) * .32) var(--accent); } }

